const rows = $input.all().map(item => item.json);

const data = rows
  .map(row => ({
    timestamp: String(row.timestamp ?? ''),
    latitude: Number(row.latitude),
    longitude: Number(row.longitude),
    pm25: Number(row.pm25),
    satellites: Number(row.satellites ?? 0),
  }))
  .filter(row =>
    Number.isFinite(row.latitude) &&
    Number.isFinite(row.longitude) &&
    Number.isFinite(row.pm25)
  );

const latest = data.length > 0 ? data[data.length - 1] : null;
const updateTime = latest?.timestamp || '--';
const center = latest ? [latest.latitude, latest.longitude] : [25.094, 121.546];

// Avoid accidentally closing the script tag if sheet data contains "<".
const safeDataJson = JSON.stringify(data).replace(/</g, '\\u003c');
const safeCenterJson = JSON.stringify(center);

const html = `<!DOCTYPE html>
<html lang="zh-Hant">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>空污共犯 PM2.5 即時監測</title>
  <link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" />
  <style>
    html, body {
      margin: 0;
      padding: 0;
      width: 100%;
      height: 100%;
      font-family: Arial, "Microsoft JhengHei", sans-serif;
      background: #f4f4f4;
    }

    #map {
      width: 100vw;
      height: 100vh;
    }

    .info-box {
      position: absolute;
      top: 16px;
      left: 70px;
      z-index: 999;
      background: rgba(0, 0, 0, 0.72);
      color: #fff;
      padding: 12px 16px;
      border-radius: 10px;
      font-size: 15px;
      line-height: 1.6;
      box-shadow: 0 4px 18px rgba(0, 0, 0, 0.25);
    }

    .info-title {
      font-weight: 700;
      font-size: 16px;
    }

    .legend {
      position: absolute;
      right: 18px;
      bottom: 32px;
      z-index: 999;
      background: rgba(0, 0, 0, 0.72);
      color: #fff;
      padding: 12px 16px;
      border-radius: 10px;
      font-size: 14px;
      line-height: 1.9;
      box-shadow: 0 4px 18px rgba(0, 0, 0, 0.25);
    }

    .legend-title {
      font-weight: 700;
      margin-bottom: 4px;
    }

    .legend-dot {
      display: inline-block;
      width: 13px;
      height: 13px;
      border-radius: 50%;
      margin-right: 7px;
      vertical-align: -1px;
    }

    .empty-message {
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
      z-index: 999;
      background: rgba(0, 0, 0, 0.72);
      color: #fff;
      padding: 16px 20px;
      border-radius: 10px;
      font-size: 16px;
      display: none;
    }

    @media (max-width: 720px) {
      .info-box {
        top: 12px;
        left: 58px;
        right: 10px;
        font-size: 13px;
        padding: 10px 12px;
      }

      .legend {
        right: 10px;
        bottom: 24px;
        font-size: 12px;
      }
    }
  </style>
</head>
<body>
  <div id="map"></div>

  <div class="info-box">
    <div class="info-title">空污共犯 PM2.5 即時監測</div>
    <div>更新時間：${updateTime}</div>
    <div>資料筆數：${data.length}</div>
    <div>頁面每 10 秒自動重新整理</div>
  </div>

  <div id="emptyMessage" class="empty-message">目前沒有可顯示的 PM2.5 資料</div>

  <div class="legend">
    <div class="legend-title">PM2.5 濃度（µg/m³）</div>
    <div><span class="legend-dot" style="background:#00e400"></span>良好 0 - 15.4</div>
    <div><span class="legend-dot" style="background:#ffff00"></span>普通 15.5 - 35.4</div>
    <div><span class="legend-dot" style="background:#ff7e00"></span>對敏感族群不健康 35.5 - 54.4</div>
    <div><span class="legend-dot" style="background:#ff0000"></span>對所有族群不健康 54.5 - 150.4</div>
    <div><span class="legend-dot" style="background:#8f3f97"></span>非常不健康 150.5 - 250.4</div>
    <div><span class="legend-dot" style="background:#7e0023"></span>危害 250.5 以上</div>
  </div>

  <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
  <script>
    const pm25Data = ${safeDataJson};
    const defaultCenter = ${safeCenterJson};

    function getColor(pm25) {
      if (pm25 < 15.5) return '#00e400';   // 良好
      if (pm25 < 35.5) return '#ffff00';   // 普通
      if (pm25 < 54.5) return '#ff7e00';   // 對敏感族群不健康
      if (pm25 < 150.5) return '#ff0000';  // 對所有族群不健康
      if (pm25 < 250.5) return '#8f3f97';  // 非常不健康
      return '#7e0023';                    // 危害
    }

    function getStatus(pm25) {
      if (pm25 < 15.5) return '良好';
      if (pm25 < 35.5) return '普通';
      if (pm25 < 54.5) return '對敏感族群不健康';
      if (pm25 < 150.5) return '對所有族群不健康';
      if (pm25 < 250.5) return '非常不健康';
      return '危害';
    }

    const map = L.map('map').setView(defaultCenter, 16);

    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
      attribution: '© OpenStreetMap'
    }).addTo(map);

    if (!pm25Data.length) {
      document.getElementById('emptyMessage').style.display = 'block';
    } else {
      const bounds = [];

      pm25Data.forEach(function(point) {
        const color = getColor(point.pm25);
        const marker = L.circleMarker([point.latitude, point.longitude], {
          radius: 8,
          color: '#ffffff',
          weight: 1,
          fillColor: color,
          fillOpacity: 0.85
        }).addTo(map);

        marker.bindPopup(
          '<strong>PM2.5：' + point.pm25 + ' µg/m³</strong><br>' +
          '狀態：' + getStatus(point.pm25) + '<br>' +
          '時間：' + point.timestamp + '<br>' +
          '衛星數：' + point.satellites + '<br>' +
          '緯度：' + point.latitude + '<br>' +
          '經度：' + point.longitude
        );

        bounds.push([point.latitude, point.longitude]);
      });

      map.fitBounds(bounds, {
        padding: [40, 40],
        maxZoom: 17
      });
    }

    // Single-webhook stable mode: refresh the whole page instead of fetch another webhook.
    setTimeout(function() {
      window.location.reload();
    }, 10000);
  </script>
</body>
</html>`;

return [
  {
    json: {
      html,
      rowCount: data.length,
      updateTime,
    }
  }
];
